from common import *

import numpy as np
from typing import *

# concepts:
# holes, enclosed regions, flood fill, background detection

# description:
# The input is a grid with a black background and a guide object made of a single color. Identify holes as black regions fully enclosed by the guide object and not connected to the grid border.
# Use flood-fill from the grid border to mark exterior black regions; any remaining black region inside the object is a hole. Fill these holes with the guide object color.

def main(input_grid):
    # Find the guide object's color (not black)
    guide_color = next(color for color in Color.NOT_BLACK if np.any(input_grid == color))

    # Initialize output grid
    output_grid = input_grid.copy()

    # Flood-fill from the border to mark exterior black regions
    exterior_mask = np.zeros_like(input_grid, dtype=bool)
    for x in range(input_grid.shape[0]):
        if input_grid[x, 0] == Color.BLACK:
            fill(input_grid, exterior_mask, x, 0)
        if input_grid[x, -1] == Color.BLACK:
            fill(input_grid, exterior_mask, x, input_grid.shape[1] - 1)
    for y in range(input_grid.shape[1]):
        if input_grid[0, y] == Color.BLACK:
            fill(input_grid, exterior_mask, 0, y)
        if input_grid[-1, y] == Color.BLACK:
            fill(input_grid, exterior_mask, input_grid.shape[0] - 1, y)

    # Fill holes (black regions not marked as exterior)
    for x in range(input_grid.shape[0]):
        for y in range(input_grid.shape[1]):
            if input_grid[x, y] == Color.BLACK and not exterior_mask[x, y]:
                output_grid[x, y] = guide_color

    return output_grid

def fill(grid, mask, x, y):
    """Flood fill to mark exterior regions."""
    to_fill = [(x, y)]
    while to_fill:
        cx, cy = to_fill.pop()
        if not mask[cx, cy] and grid[cx, cy] == Color.BLACK:
            mask[cx, cy] = True
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:  # 4-way connectivity
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < grid.shape[0] and 0 <= ny < grid.shape[1]:
                    to_fill.append((nx, ny))

def generate_input():
    # Generate a grid with a black background
    n = np.random.randint(10, 20)
    grid = np.full((n, n), Color.BLACK)

    # Create a guide object
    guide_color = np.random.choice(list(Color.NOT_BLACK))
    obj_size = np.random.randint(3, min(n // 2, 7))
    guide_object = np.full((obj_size, obj_size), guide_color)
    guide_object[1:-1, 1:-1] = Color.BLACK  # Make it hollow

    # Place the guide object in the grid
    try:
        x, y = random_free_location_for_sprite(grid, guide_object, padding=1)
        blit_sprite(grid, guide_object, x, y)
    except ValueError:
        return generate_input()

    return grid
